import assert from "node:assert/strict";
import test from "node:test";
import { processTimeweb } from "../services/timewebAiService.js";
import { mapPhotoInfo } from "../utils/photos.js";
import { getFormattedText, getFormattedHtml } from "../../client/src/utils/formattedClipboard.js";

// Responses below are supplied by the test, not generated by an LLM. These tests
// check the outgoing instruction and lossless processing of a possible answer.
const paragraph = text => ({ type: "paragraph", text });
const heading = text => ({ type: "heading", text });
const header = [paragraph("В районный суд ______"), paragraph("Заявитель: ______"),
  paragraph("адрес: ______; телефон: +7 (___) ___-__-__")];
const subtitle = "об установлении факта принятия наследства";
const requestBody = paragraph("Прошу установить факт. Дата: __.__.____; подпись: ______.");
const cases = [
  {
    name: "application with an OCR title before the header",
    source: ["Заявление", ...header.map(b => b.text), subtitle, requestBody.text].join("\n"),
    blocks: [...header, heading("Заявление"), heading(subtitle), requestBody]
  },
  {
    name: "complaint whose header already precedes the title",
    source: ["Руководителю организации ______", "От заявителя ______", "Жалоба", "Прошу рассмотреть обращение."].join("\n"),
    blocks: [paragraph("Руководителю организации ______"), paragraph("От заявителя ______"),
      heading("Жалоба"), paragraph("Прошу рассмотреть обращение.")]
  },
  {
    name: "ordinary letter without a header",
    source: "Письмо\nДобрый день!\nСообщаю адрес для доставки: ______.",
    blocks: [heading("Письмо"), paragraph("Добрый день!"), paragraph("Сообщаю адрес для доставки: ______.")]
  },
  {
    name: "court and application words quoted inside prose do not create a header",
    source: "Памятка\nВ тексте встречаются слова «В районный суд» и «Заявление».\nЭто пример цитаты.",
    blocks: [heading("Памятка"), paragraph("В тексте встречаются слова «В районный суд» и «Заявление»."),
      paragraph("Это пример цитаты.")]
  },
  {
    name: "application retains list markers and the table anchor after the body",
    source: ["Заявление", ...header.map(b => b.text), subtitle, requestBody.text,
      "1. Копия заявления", "2. Квитанция", "Расходы\nПочта 100,00\nКопии 20,00"].join("\n"),
    blocks: [...header, heading("Заявление"), heading(subtitle), requestBody,
      { type: "list", ordered: true, items: ["Копия заявления", "Квитанция"] },
      { type: "table_source", tableId: "table-1", text: "Расходы\nПочта 100,00\nКопии 20,00" }]
  }
];

for (const scenario of cases) test(`offline document order: ${scenario.name}`, async () => {
  const expected = { blocks: scenario.blocks };
  const response = { title: "Синтетическая проверка", summary: "", category: "документ", section: "документы",
    topic: "", tags: [], formattedContent: expected, hasTable: scenario.blocks.some(b => b.type === "table_source"),
    hasFormulas: false, hasRecognitionErrors: false, textQuality: "full_text", corrections: [], notes: "" };
  const original = structuredClone(scenario);
  let requests = 0;
  let captured;
  const result = await processTimeweb(scenario.source, {
    timeweb: { enabled: true, apiKey: "synthetic-only", model: "synthetic-offline",
      baseURL: "http://127.0.0.1:9/v1", timeoutMs: 1000, maxTokens: 6000 },
    logger: { info() {}, warn() {}, error() {} },
    fetchImplementation: async (_url, options) => {
      requests++;
      captured = JSON.parse(options.body);
      return new Response(JSON.stringify({ choices: [{ message: { content: JSON.stringify(response) }, finish_reason: "stop" }],
        usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 } }),
      { status: 200, headers: { "Content-Type": "application/json" } });
    }
  });
  assert.equal(requests, 1, "one supplied answer, no automatic retry or fallback");
  assert.equal(result.error, undefined);
  assert.equal(captured.messages[1].content.split("OCR-текст:\n").at(-1), scenario.source,
    "the prompt does not pre-reorder or rewrite the original OCR");
  assert.match(captured.messages[0].content, /шапка → заголовок и подзаголовок → основной текст/u);
  assert.match(captured.messages[0].content, /Одного упоминания суда, адреса или слова «Заявление» недостаточно/u);
  assert.deepEqual(result.formattedContent, expected, "normalization preserves the supplied block order and content");
  assert.equal(result.sourceText, scenario.source);
  assert.deepEqual(result.corrections, []);
  const info = mapPhotoInfo({ filename: "synthetic.jpg", status: "processed", ocr_text: result.sourceText,
    clean_text: result.cleanText, formatted_content: result.formattedContent, has_table: response.hasTable });
  assert.equal(info.text, scenario.source, "the original OCR tab remains unchanged");
  assert.deepEqual(info.formattedContent, expected);
  assert.equal(info.cleanText, getFormattedText(expected), "plain and formatted variants have the same block order");
  const html = getFormattedHtml(expected);
  let position = -1;
  for (const block of scenario.blocks.filter(b => b.type !== "list")) {
    // HTML escapes punctuation; the heading text used here contains no markup.
    if (block.type !== "heading") continue;
    const next = html.indexOf(`<h3>${block.text}</h3>`);
    assert.ok(next > position, "headings stay in their supplied order in rich copy");
    position = next;
  }
  assert.deepEqual(scenario, original, "the test input is never mutated");
});
